const E=LifeEngine,F=LifeFlow,KEY='lifeline-test-v1',labels={money:'Деньги',skill:'Навыки',health:'Здоровье',energy:'Силы',bond:'Близость',joy:'Радость'},icons={money:'◈',skill:'✧',health:'♡',energy:'ϟ',bond:'❋',joy:'☀'};let state,tab='story';try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.v!==1||!state.origin)state=E.fresh();}catch{state=E.fresh();}if(state.goal&&!Number.isInteger(state.goal.step))state.goal=null;E.ensureChildhood(state);F.ensure(state);state.flow.playing=false;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function birthplace(s=state){return esc(s.origin.country);}
function birthChance(s=state){return (s.origin.birthProbability*100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:4})+'%';}
function birthSourceLink(){return `<button class="birth-source-link" data-birth-source>${state.origin.birthDataYear?'Почему эта страна? ООН · '+state.origin.birthDataYear:'Как было выбрано место рождения?'}</button>`;}
function showBirthSource(){const d=E.birthData,o=state.origin;openDialog(`<span class="eyebrow">МЕСТО РОЖДЕНИЯ</span><h2>${birthplace()}</h2>${o.birthDataYear?`<p>В этой стране или территории оценено <strong>${o.births.toLocaleString('ru-RU')} живорождений</strong> за ${o.birthDataYear} год.</p><p>Её доля в выборке — <strong>${birthChance()}</strong>, примерно 1 из ${Math.round(1/o.birthProbability).toLocaleString('ru-RU')} рождений.</p><div class="forecast"><h3>Как выбирается страна</h3><p>Число рождений здесь ÷ сумма рождений во всех ${d.countryCount} странах и территориях набора. Чем больше рождений, тем выше вероятность.</p><p>Сумма весов: ${d.totalBirths.toLocaleString('ru-RU')}. Использованы оценки за ${d.year} год, с обновлением данных по Того. Регионы и мировые итоги исключены, чтобы не считать рождения дважды.</p></div>`:'<p>Это сохранение создано в старой версии: один из четырёх заранее заданных стартов выбирался с равными шансами. Этот выбор не был статистическим.</p><p>Чтобы получить место рождения по данным ООН, начните новую жизнь. Текущее сохранение автоматически не заменяется.</p>'}<p><a href="${d.sourceUrl}" target="_blank" rel="noopener">Источник: ООН, World Population Prospects 2024 ↗</a></p><p><a href="births-2023.csv" download>Скачать использованные веса стран (CSV)</a></p><p class="tiny">Статистика определяет страну или территорию. Город не выбирается: для него ещё нет отдельного набора данных. Имена и семейные истории художественные; благосостояние, отношения и параметры здоровья пока не откалиброваны по странам. Срез 2023 года не превращает дальнейшую историю в прогноз реальных событий.</p>`);}
function cohortView(){const c=LifeCohort.estimate(F.ensure(state).months);return `<div class="cohort-line"><div><span>Родившиеся с вами в один день · мир</span><p>По статистической модели живы ≈ <strong>${c.aliveOthers.toLocaleString('ru-RU')}</strong> из ${c.initialOthers.toLocaleString('ru-RU')} других детей</p></div><button class="birth-source-link" data-cohort-source aria-label="Как рассчитано число живых ровесников">ООН · ${c.year} ⓘ</button></div>`;}
function showCohortSource(){const c=LifeCohort.estimate(F.ensure(state).months);openDialog(`<span class="eyebrow">РОВЕСНИКИ · ВЕСЬ МИР</span><h2>Оценка для одного дня рождения</h2><p>В среднем за день в мире рождается примерно ${(c.initialOthers+1).toLocaleString('ru-RU')} детей. Один из них — ваш персонаж. Счётчик показывает оценку для остальных.</p><p>К вашему игровому возрасту при смертности 2023 года доля выживших в модельной группе составляет около ${(c.probability*100).toLocaleString('ru-RU',{maximumFractionDigits:2})}%.</p><div class="forecast"><h3>Как считаем</h3><p>Число других детей при рождении = округлённая сумма рождений за 2023 год по 237 странам и территориям ÷ 365, минус один персонаж. Затем умножаем её на вероятность дожить до текущего возраста из мировой таблицы ООН: l(x) ÷ l(0).</p><p>Для возраста между целыми годами используем линейную интерполяцию. Особенно в первый год это грубое приближение: смерти в действительности распределены по месяцам неравномерно.</p></div><p>Это средний условный день, а не реальная группа людей с известной датой рождения. Таблица периодная: мы сохраняем смертность 2023 года для всех возрастов. Будущие изменения медицины и условий жизни здесь не прогнозируются. Это не вероятность смерти вашего персонажа; ваши решения этот счётчик не меняют.</p><p><a href="https://population.un.org/wpp/" target="_blank" rel="noopener">Источник: ООН, World Population Prospects 2024 ↗</a></p><p class="tiny">Мир, оба пола, 2023 год. Показатель l(x), база 100 000 рождений. CC BY 3.0 IGO. Данные рождаемости включают обновление для Того.</p>`);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='✓ Сохранено на устройстве';}catch{$('#save-status').textContent='Сохранение недоступно';}}
function stage(){return state.age===0?'Рождение':state.age<6?'Первые годы':state.age<17?'Детство':state.age<32?'Начало пути':state.age<58?'Взрослая жизнь':'Новый ритм';}
function scene(){return renderPixelScene(state);}
function stats(){return Object.keys(labels).map(k=>`<div class="stat"><div><span>${icons[k]} ${labels[k]}</span><strong>${state.stats[k]}<small>/100</small></strong></div><div class="bar"><i style="width:${state.stats[k]}%;background:${state.stats[k]<30?'#b87964':'#8a9875'}"></i></div></div>`).join('');}
function goalCard(){if(state.age<6)return '';if(state.ended)return `<span class="eyebrow">БЛИЖАЙШИЕ ЦЕЛИ</span><h3>Достигнуто целей: ${state.completed.length}</h3>`;if(!state.goal)return `<button class="goal-empty" data-goal>＋ Выбрать ближайшую цель <span>${E.availableGoals(state).some(g=>g.suggested)?'Есть желание, связанное с вашими прежними интересами':'Можно выбрать позже или играть без цели'}</span></button>`;let g=state.goal;return `<div class="goal-head"><span class="eyebrow">ХОЧУ: ${E.chapters[state.step][0]} ЛЕТ</span><button class="text-btn" data-goal>Изменить</button></div><h3>${esc(g.name)}</h3><p class="goal-instruction">Чтобы выполнить цель, выберите действие<br><strong>«${esc(g.action)}»</strong> в текущей ситуации.</p>`;}
function ageText(age){return age+' '+(age===1?'год':age>=2&&age<=4?'года':'лет');}
function familyPanel(){const f=state.family;return `<div class="family-panel"><span class="eyebrow">ТЕ, КОГО ВЫ УЗНАЁТЕ ПЕРВЫМИ</span><div class="family-members"><span><i class="family-avatar mom">${esc(f.mother.name[0])}</i><b>${esc(f.mother.name)}</b><small>мама · ${esc(F.occupation(state,'mother'))}</small></span><span><i class="family-avatar dad">${esc(f.father.name[0])}</i><b>${esc(f.father.name)}</b><small>папа · ${esc(F.occupation(state,'father'))}</small></span><span><i class="family-avatar gran">${esc(f.grandmother.name[0])}</i><b>${esc(f.grandmother.name)}</b><small>бабушка · ${esc(F.occupation(state,'grandmother'))}</small></span></div></div>`;}
function personalityPanel(){let traits=E.traitSummary(state);if(!traits.length)return '';return `<div class="personality-panel"><span class="eyebrow">${state.age<6?'ПОСТЕПЕННО УЗНАЁМ ВАС':'ЧТО УЖЕ ЗАМЕТНО'}</span><p>${esc(state.origin.name)} ${traits.map(t=>esc(t.text)).join('; ')}.</p><small>Это наблюдения из вашей истории. Характер ещё будет меняться.</small></div>`;}
function earlyView(){const c=E.earlyScene(state);return `<div class="chapter-line"><span>ПЕРВЫЕ ГОДЫ · ${state.childhood.step+1} / 5</span><span>${ageText(c.age).toUpperCase()}</span></div><h2 class="event-title">${esc(c.title)}</h2><p class="event-desc early-story">${esc(c.text)}</p><div class="choices early-choices">${c.options.map((o,i)=>`<button class="choice" data-early="${i}"><span class="choice-num">0${i+1}</span><span><b>${esc(o.title)}</b><small>${esc(o.desc)}</small></span><span class="plain-arrow" aria-hidden="true">→</span></button>`).join('')}</div><p class="tiny note">Здесь нет правильного ответа. Вы узнаёте, как ваш ребёнок откликается на мир.</p>`;}
function choiceView(){let c=E.chapters[state.step];return `<div class="chapter-line"><span>ГЛАВА ${String(state.step+1).padStart(2,'0')} / ${E.chapters.length}</span><span>${c[0]} ЛЕТ</span></div><h2 class="event-title">${c[1]}</h2><p class="event-desc">${c[2]}</p><div class="choices">${c[3].map((o,i)=>`<button class="choice" data-choice="${i}"><span class="choice-num">0${i+1}</span><span><b>${o.title}</b>${state.goal&&state.goal.step===state.step&&state.goal.index===i?'<span class="goal-match">Действие для вашей цели</span>':''}<small>${o.desc}</small><span class="effects">${Object.entries(o.effect).map(([k,v])=>`<em class="${v<0?'negative':''}">${labels[k]} ${v>0?'+':''}${v}</em>`).join('')}</span></span><span class="choice-arrow">↗</span></button>`).join('')}</div><p class="tiny note">Показаны прямые эффекты. Нагрузка и случайные события тоже могут повлиять на результат.</p>`;}
function peopleView(){const f=state.family;return `<h2 class="event-title">Лица вашей жизни</h2>${familyPanel()}<div class="forecast"><h3>Как живётся дома</h3><p>${esc(f.home)}</p><p>${esc(f.climate)}</p></div>${state.age>=5?`<div class="person-card"><div class="avatar">С</div><div><h3>Саша</h3><p>${state.age<17?'Школьник':state.age<22?'Учится на ветеринара':'Ветеринар'} · ${state.stats.bond>65?'вы часто проводите время вместе':'общение может стать ближе'}</p></div></div><p class="event-desc">${state.childhood.moments.length?'Вы познакомились над городом из кубиков. Рядом с ним можно пробовать новое или просто играть.':'Впереди совместные игры и разговоры.'}</p>`:''}<p class="tiny">Достаток не определяет любовь и безопасность в семье. Поведение взрослых — их ответственность.</p>`;}
function modelView(){return `<h2 class="event-title">Что основано на данных</h2><div class="forecast"><h3>Страна рождения — статистика ООН</h3><p>Использованы оценки числа живорождений за ${E.birthData.year} год из World Population Prospects 2024, с обновлением для Того. В выборке ${E.birthData.countryCount} стран и территорий. Вероятность равна доле рождений страны в сумме весов набора.</p><p>Города не подставляются: для них нужен отдельный источник.</p>${birthSourceLink()}</div>${!state.origin.birthDataYear?'<p class="event-desc">Ваше сохранение создано до этого обновления. Его место рождения осталось прежним и не стало статистическим задним числом. Новый алгоритм работает при начале новой жизни.</p>':''}<h3>Течение времени — тест</h3><p class="event-desc">Время идёт по месяцам. Между решениями происходят повседневные события, рабочие и семейные изменения. Для важного выбора время останавливается. Пауза и скорость меняют просмотр; при закрытой вкладке время не идёт. Все новости в ленте — вымышленные события мира игры, не реальные новости страны.</p><h3>Ровесники по всему миру</h3><p class="event-desc">Счётчик использует среднее число рождений за день и мировую таблицу выживания ООН за 2023 год. Это условная группа при неизменной смертности 2023 года, а не подсчёт конкретных людей или прогноз жизни персонажа.</p><button class="birth-source-link" data-cohort-source>Как рассчитано число ровесников?</button><h3>Остальные системы — тестовая модель</h3><p class="event-desc">Достаток семьи, отношения, характер, профессии, эффекты решений и события пока заданы для проверки игры. Национальных распределений доходов, образования, здоровья и семейных условий ещё нет. Все шкалы от 0 до 100 условны.</p><h3>Характер без ярлыков</h3><p class="event-desc">Ранние реакции помогают постепенно замечать интерес к исследованию, общению, выдумке или привычному ритму. Это авторская модель, а не психологический тест. Сложная семейная сцена не присваивает ребёнку черты характера.</p><h3>Граница сценария</h3><p class="event-desc">Возраст 76 — фиксированный конец тестовой истории, не прогноз смерти. Исторические и будущие режимы ещё не подключены. Истории и имена художественные; они не описывают типичную жизнь всех жителей страны.</p><button class="secondary" id="export">Скачать историю жизни ↓</button>`;}
function ending(){return `<span class="eyebrow">КОНЕЦ ТЕСТОВОЙ ИСТОРИИ · ${state.age} ЛЕТ</span><h2 class="event-title">Жизнь сложилась<br>по-своему.</h2><p class="event-desc">Важных решений: ${state.history.length}. Сохранённых воспоминаний: ${state.memories.length}. Достигнутых ближайших целей: ${state.completed.length}. Единой оценки жизни здесь нет.</p><h3>С чего начали — к чему пришли</h3><div class="comparison">${Object.keys(labels).map(k=>`<div><span>${labels[k]}</span><b>${state.baseline[k]} <i>→</i> ${state.stats[k]}</b></div>`).join('')}</div><p class="tiny">Это сравнение с исходными игровыми ресурсами, не со статистическим прогнозом. История остановилась по границе теста, а не из-за смерти персонажа.</p><button class="primary" id="album">Открыть историю жизни <span>↗</span></button><button class="secondary" id="export">Скачать историю ↓</button>`;}
function birthScreen(){return `<section class="birth-screen"><div class="birth-symbol" aria-hidden="true">✳</div><h1>Ваша история<br>ещё не началась<span>.</span></h1><p class="lead">Родитесь в случайной семье и узнайте,<br>с чего начнётся ваша жизнь.</p><button class="primary" id="be-born">Родиться <span>→</span></button><p class="tiny">Тест механик · данные демонстрационные</p></section>`;}
function openDialog(html){$('#dialog').className='';$('#dialog').innerHTML=`<button class="close icon" id="close-dialog" aria-label="Закрыть">×</button>${html}`;$('#dialog').showModal();$('#close-dialog').onclick=()=>$('#dialog').close();}
function goalPicker(){if(state.age<6||state.ended)return;const goals=E.availableGoals(state);let selected=state.goal?.id||null;openDialog(`<div class="goal-modal-header"><span class="eyebrow">БЛИЖАЙШАЯ ЦЕЛЬ · ${E.chapters[state.step][0]} ЛЕТ</span><h2>${state.age<17?'Чего хочется ребёнку?':'Чего хочется сейчас?'}</h2><p>Выберите одно желание. Потом помогите персонажу выполнить его в игре.</p></div><div class="goal-modal-body"><div class="goal-options" role="radiogroup" aria-label="Ближайшая цель">${goals.map(g=>`<button class="goal-option ${selected===g.id?'selected':''}" role="radio" aria-checked="${selected===g.id}" data-pick="${g.id}"><span class="goal-radio" aria-hidden="true"></span><span><b>${esc(g.name)}</b>${g.suggested?`<span class="goal-match">${esc(g.reason)}</span>`:''}<small>Как выполнить: выбрать «${esc(g.action)}».</small></span></button>`).join('')}</div></div><div class="goal-modal-footer"><p id="goal-selection">${selected?'Выбрано: '+esc(state.goal.name):'Сначала выберите желание выше.'}</p><button class="primary" id="confirm-goal" ${selected?'':'disabled'}>Выбрать цель</button><button class="text-btn" id="no-goal">Пока без цели</button></div>`);$('#dialog').className='goal-dialog';document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selected=b.dataset.pick;document.querySelectorAll('[data-pick]').forEach(x=>{x.classList.toggle('selected',x.dataset.pick===selected);x.setAttribute('aria-checked',String(x.dataset.pick===selected));});$('#goal-selection').textContent='Выбрано: '+goals.find(g=>g.id===selected).name;$('#confirm-goal').disabled=false;});$('#confirm-goal').onclick=()=>{if(!selected)return;E.setGoal(state,selected);save();$('#dialog').close();render();};$('#no-goal').onclick=()=>{state.goal=null;save();$('#dialog').close();render();};}
const flowTypes={everyday:'Повседневность',family:'Семья',choice:'Ваш выбор',consequence:'Последствие',news:'Новости мира игры',career:'Работа',milestone:'Важное событие',goal:'Цель',event:'Событие'};
function flowAge(month){const years=Math.floor(month/12),months=month%12;return ageText(years)+(months?' '+months+' мес.':'');}
function flowControls(){const f=F.ensure(state),p=F.pending(state);return `<div class="time-controls"><button id="time-toggle" ${p||state.ended?'disabled':''}>${p?'Нужен ваш выбор':f.playing?'Ⅱ Пауза':'▷ Продолжить'}</button><div class="speed-controls" aria-label="Скорость времени">${[1,3,6].map(n=>`<button data-speed="${n}" class="${f.speed===n?'selected':''}" aria-pressed="${f.speed===n}">${n}×</button>`).join('')}</div><button class="month-step" id="month-step" ${p||state.ended?'disabled':''} aria-label="Продвинуть время на один месяц">+ месяц</button></div>`;}
function liveStage(){const f=F.ensure(state),p=F.pending(state);return `<div class="live-stage ${p||!f.playing||state.ended?'motion-paused':''}"><div class="live-identity"><div><strong>${esc(state.origin.name)}</strong><span>${flowAge(f.months)}</span><small>${esc(F.occupation(state))}</small></div><span class="live-status"><i class="${p||!f.playing?'paused':''}"></i>${state.ended?'История завершена':p?'Время ждёт вас':f.playing?'Жизнь идёт':'Пауза'}</span></div><div class="live-scene-frame">${renderLiveScene(state)}<span class="activity-label">${F.names[F.activeScene(state)]}</span></div>${flowControls()}${cohortView()}</div>`;}
function feedView(){const f=F.ensure(state),events=f.feed.slice(-8).reverse();return `<section class="live-feed" aria-label="Лента жизни"><div class="feed-heading"><span>ЛЕНТА ЖИЗНИ</span><button class="text-btn" id="all-events">Вся история</button></div><div class="feed-scroll">${events.length?events.map(ev=>`<article class="feed-row feed-${ev.type}"><span>${flowAge(ev.month)}</span><div><b>${flowTypes[ev.type]||'Событие'}</b><p>${esc(ev.text)}</p></div></article>`).join(''):'<p class="feed-empty">Начался первый день вашей жизни. Скоро здесь появятся события.</p>'}</div></section>`;}
function sideView(p){return `<div class="chapter-line"><span>МОМЕНТ ЖИЗНИ</span><span>ВРЕМЯ НА ПАУЗЕ</span></div><h2 class="event-title">${esc(p.title)}</h2><p class="event-desc">${esc(p.text)}</p><div class="choices">${p.options.map((o,i)=>`<button class="choice" data-side="${i}"><span class="choice-num">0${i+1}</span><span><b>${esc(o[0])}</b><small>${esc(o[1])}</small></span><span class="plain-arrow" aria-hidden="true">→</span></button>`).join('')}</div>`;}
function quietView(){const f=F.ensure(state);return `<div class="between-choices"><span class="eyebrow">МЕЖДУ РЕШЕНИЯМИ</span><h2>${state.age===0&&f.months<3?'Первые дни дома':'Жизнь продолжается'}</h2><p>${state.age===0&&f.months<3?`Мама ${esc(state.family.mother.name)} — ${esc(state.family.mother.job)}. Папа ${esc(state.family.father.name)} — ${esc(state.family.father.job)}. Пока ваш мир — это голоса и лица близких.`:'Сейчас решения не требуется. Можно наблюдать за персонажем, читать события или изменить скорость времени.'}</p>${state.age===0&&f.months<3?`<p>${esc(state.family.home)} ${esc(state.family.climate)}</p>`:''}<p class="tiny">Новости и повседневные события в этом тесте вымышленные. Страна рождения и оценка выживания ровесников основаны на данных ООН. Остальные системы пока тестовые.</p></div>`;}
function storyContent(){const p=F.pending(state);if(state.ended)return ending();return p?(p.kind==='early'?earlyView():p.kind==='chapter'?choiceView():sideView(p)):quietView();}
function render(){const f=F.ensure(state);if(state.born&&!state.started)state.started=true;if(!state.started){$('#app').innerHTML=birthScreen();$('#be-born').onclick=()=>{F.begin(state);save();render();};return;}const active=document.activeElement?.id;$('#app').innerHTML=`<div class="flow-layout"><section class="flow-main"><nav class="tabs" aria-label="Разделы игры">${[['story','Жизнь'],['history','История'],['people','Люди'],['model','О модели']].map(([key,title])=>`<button data-tab="${key}" class="${key===tab?'active':''}">${title}</button>`).join('')}</nav>${tab==='story'?`${liveStage()}${feedView()}<div class="flow-story">${storyContent()}</div>`:tab==='history'?historyView():tab==='people'?peopleView():modelView()}</section><aside class="flow-sidebar"><div class="side-identity"><span class="eyebrow">ВАШ ПЕРСОНАЖ</span><h2>${esc(state.origin.name)}</h2><p>${birthplace()} · ${flowAge(f.months)}</p><strong>${esc(F.occupation(state))}</strong>${birthSourceLink()}</div>${familyPanel()}${state.age>=6?`<div class="resources">${stats()}</div>`:''}${personalityPanel()}${F.pending(state)?.kind==='chapter'&&state.age>=6?`<div class="goal-box">${goalCard()}</div>`:''}<p class="tiny test-label">Тест течения жизни · профессии, новости и события пока заданы для настройки логики.</p></aside></div>`;bind();if(active&&$('#'+active))$('#'+active).focus({preventScroll:true});}
function historyView(){const f=F.ensure(state);return `<h2 class="event-title">История жизни</h2><p class="muted">Решения и то, что происходило между ними. Событий: ${f.feed.length}.</p><button class="secondary" id="export">Скачать всю историю</button><div class="history-feed">${f.feed.slice(-100).reverse().map(ev=>`<article class="feed-row feed-${ev.type}"><span>${flowAge(ev.month)}</span><div><b>${flowTypes[ev.type]||'Событие'}</b><p>${esc(ev.text)}</p></div></article>`).join('')||'<p class="empty">История только начинается.</p>'}</div>${f.feed.length>100?'<p class="tiny">Показаны последние 100 событий. Полная история доступна для скачивания.</p>':''}`;}
function bind(){document.querySelectorAll('[data-cohort-source]').forEach(b=>b.onclick=showCohortSource);document.querySelectorAll('[data-birth-source]').forEach(b=>b.onclick=showBirthSource);for(const kind of ['early','choice','side'])document.querySelectorAll('[data-'+kind+']').forEach(b=>b.onclick=()=>{if(F.resolve(state,Number(b.dataset[kind]))){save();render();}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;save();render();});document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=goalPicker);document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{state.flow.speed=Number(b.dataset.speed);save();render();});if($('#time-toggle'))$('#time-toggle').onclick=()=>{state.flow.playing=!state.flow.playing;save();render();};if($('#month-step'))$('#month-step').onclick=()=>{state.flow.playing=false;F.advance(state);save();render();};if($('#all-events'))$('#all-events').onclick=()=>{tab='history';render();};if($('#album'))$('#album').onclick=()=>{tab='history';render();};if($('#export'))$('#export').onclick=download;}
function download(){const text='ЛИНИЯ ЖИЗНИ — ПРОТОТИП\n'+state.origin.name+', '+state.origin.country+'\nПрофессия / занятие: '+F.occupation(state)+'\nНовости мира игры вымышлены.\n\n'+F.ensure(state).feed.map(e=>flowAge(e.month)+' · '+(flowTypes[e.type]||'Событие')+'\n'+e.text).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='life-story.txt';a.click();URL.revokeObjectURL(url);}
let tickElapsed=0,lastFrame=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.min(250,now-lastFrame);lastFrame=now;const f=F.ensure(state);if(!state.started||state.ended||!f.playing||tab!=='story'||document.hidden||$('#dialog').open||F.pending(state)){tickElapsed=0;return;}tickElapsed+=dt*f.speed;if(tickElapsed>=1800){tickElapsed-=1800;if(F.advance(state)){save();render();}}},100);

$('#restart').onclick=()=>{openDialog('<h2>Начать другую жизнь?</h2><p class="muted">Текущее сохранение на этом устройстве будет заменено. Историю можно предварительно скачать.</p><button class="secondary" id="keep-history">Скачать историю</button><button class="primary" id="confirm-restart">Начать заново →</button>');$('#keep-history').onclick=download;$('#confirm-restart').onclick=()=>{state=E.fresh();F.ensure(state);tab='story';save();$('#dialog').close();render();};};$('#help').onclick=()=>openDialog('<span class="eyebrow">ИГРОВАЯ ЛАБОРАТОРИЯ · 0.1</span><h2>От первых воспоминаний до собственной жизни</h2><p>Наблюдайте за жизнью в маленькой сцене и читайте ленту под ней. Время идёт по месяцам. Важные решения приостанавливают ход времени. Можно поставить паузу, изменить скорость или перейти на один месяц вперёд. Профессии, семейные события и новости пока служат проверке логики.</p><p>Прогресс сохраняется только в этом браузере. Страна рождения выбирается по данным ООН за 2023 год. Остальные системы тестовые; статистический прогноз жизни, полноценная экономика и самостоятельная жизнь близких появятся в следующих сборках.</p><p class="tiny">Иллюстрация — временный визуальный эскиз, а не утверждённый стиль игры.</p>');render();
